"use client";

import { Meter } from "@/components/audio/elements/meter";
import { useSimulatedLevels } from "@/hooks/use-simulated-levels";

const SCALE = [-48, -24, -12, -6, 0];

export function MeterHorizontalDemo() {
  const source = useSimulatedLevels(2);
  return (
    <Meter
      aria-label="Stereo output"
      marks={SCALE}
      orientation="horizontal"
      size="sm"
      source={source}
      warnThreshold={-12}
    />
  );
}
